:root {
  --ink: #0a0e13;
  --panel: #101720;
  --line: #1d2731;
  --text: #e8eef6;
  --dim: #8fa0b4;
  --rise: #3ddc84;
  --fall: #ff6b6b;
  --mark: #f5c451;
  color-scheme: dark;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font: 14px/1.45 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

.masthead {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 22px 28px 18px;
  border-bottom: 1px solid var(--line);
}

h1 { margin: 0; font-size: 21px; letter-spacing: -0.01em; }

.lede { margin: 6px 0 0; max-width: 640px; color: var(--dim); }

.tally {
  display: grid;
  grid-template-columns: auto auto;
  gap: 2px 10px;
  margin: 0;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.tally dt { color: var(--dim); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.tally dd { margin: 0; font-weight: 600; }

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 14px;
  padding: 12px 28px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}

.controls label { display: grid; gap: 3px; color: var(--dim); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.controls label.check { display: flex; align-items: center; gap: 6px; text-transform: none; letter-spacing: 0; font-size: 13px; }

select, input, button {
  background: var(--ink);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 6px 9px;
  font: inherit;
}

select:focus-visible, input:focus-visible, button:focus-visible, th:focus-visible {
  outline: 2px solid var(--mark);
  outline-offset: 1px;
}

button { cursor: pointer; }
button:hover { border-color: var(--dim); }

.status { margin: 0; padding: 8px 28px; color: var(--dim); font-size: 12px; }

main { padding: 0 28px 48px; overflow-x: auto; }

table { width: 100%; border-collapse: collapse; }

caption { caption-side: top; text-align: left; padding: 8px 0 10px; color: var(--dim); font-size: 12px; }

th, td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line); white-space: nowrap; }

th {
  position: sticky;
  top: 0;
  background: var(--ink);
  color: var(--dim);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  cursor: pointer;
  user-select: none;
}

th[aria-sort="descending"] { color: var(--text); }
th[aria-sort="descending"]::after { content: " v"; }
th[aria-sort="ascending"]::after { content: " ^"; }

tbody tr:hover { background: var(--panel); cursor: pointer; }
tbody tr:focus-visible { outline: 2px solid var(--mark); outline-offset: -2px; }

td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }

td.name { font-weight: 600; }
td.name.on-watch { color: var(--mark); }
td.rise { color: var(--rise); }
td.fall { color: var(--fall); }
td.dim { color: var(--dim); }

#drawer {
  position: fixed;
  inset: 0 0 0 auto;
  width: min(460px, 96vw);
  overflow-y: auto;
  padding: 20px 24px 48px;
  background: var(--panel);
  border-left: 1px solid var(--line);
  box-shadow: -24px 0 48px rgb(0 0 0 / 45%);
}

#drawer[hidden] { display: none; }

#close { position: sticky; top: 0; float: right; }

#detail h2 { margin: 0 0 2px; font-size: 18px; }
#detail .sub { margin: 0 0 14px; color: var(--dim); }
#detail h3 { margin: 22px 0 8px; font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--dim); }

.kv { display: grid; grid-template-columns: 132px 1fr; gap: 5px 14px; margin: 0; }
.kv dt { color: var(--dim); }
.kv dd { margin: 0; font-variant-numeric: tabular-nums; }

.bars { display: grid; gap: 6px; }
.bar { display: grid; grid-template-columns: 112px 1fr 44px; align-items: center; gap: 8px; font-size: 12px; color: var(--dim); }
.bar span.track { height: 6px; background: var(--line); border-radius: 3px; overflow: hidden; }
.bar span.fill { display: block; height: 100%; background: var(--mark); }

ol.steps { padding-left: 18px; }
ol.steps li { margin: 9px 0; color: var(--text); }

@media (max-width: 720px) {
  .masthead { flex-direction: column; }
  .tally { grid-template-columns: repeat(6, auto); text-align: left; }
}
